} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  const parentMenu = this.elements.parentMenu;
  if (parentMenu) {
    const currentMenuItem = parentMenu.elements.menuItems[parentMenu.currentChild];
    if (currentMenuItem && currentMenuItem.isSubmenuItem) {
      currentMenuItem.elements.toggle.close();
    }
  }
  if (parentMenu) {
    parentMenu.focusCurrentChild();
  }
}
